package com.personal.meditation;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.webkit.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
public final class MainActivity extends Activity {
 private WebView web;private Settings settings;private CuePlayer preview;private String pendingRole;private boolean ready;private Object backCallback;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);settings=new Settings(this);preview=new CuePlayer(this);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(32,55,71));root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web=new WebView(this);web.setBackgroundColor(Color.rgb(32,55,71));web.setAlpha(0);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);root.requestApplyInsets();getWindow().setStatusBarColor(Color.rgb(32,55,71));getWindow().setNavigationBarColor(Color.rgb(90,92,97));
 WebSettings prefs=web.getSettings();prefs.setJavaScriptEnabled(true);prefs.setAllowFileAccess(false);prefs.setAllowContentAccess(false);prefs.setBlockNetworkLoads(true);prefs.setDomStorageEnabled(false);prefs.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"MeditationNative");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});
 try(InputStream input=getAssets().open("index.html")){ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[8192];for(int n;(n=input.read(buffer))!=-1;)output.write(buffer,0,n);web.loadDataWithBaseURL("https://meditation.local/",output.toString(StandardCharsets.UTF_8.name()),"text/html","UTF-8",null);}catch(IOException failed){finish();}if(Build.VERSION.SDK_INT>=33)backCallback=BackApi33.register(this,this::back);}
 private void back(){if(web!=null&&ready)web.evaluateJavascript("MeditationApp.back()",value->{if(!"true".equals(value))finish();});else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onPause(){if(preview!=null)preview.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();refresh();}
 private void refresh(){if(web!=null&&ready)web.evaluateJavascript("window.MeditationApp&&MeditationApp.refresh()",null);}
 @Override protected void onDestroy(){if(Build.VERSION.SDK_INT>=33&&backCallback!=null)BackApi33.unregister(this,backCallback);if(preview!=null)preview.stop();if(web!=null){web.removeJavascriptInterface("MeditationNative");web.destroy();web=null;}super.onDestroy();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=40||pendingRole==null)return;String role=pendingRole;pendingRole=null;if(result!=RESULT_OK||data==null||data.getData()==null){refresh();return;}Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);String name="Chosen audio file";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}try(android.content.res.AssetFileDescriptor check=getContentResolver().openAssetFileDescriptor(uri,"r")){if(check==null)throw new IOException("No audio");}if(!settings.custom(role,uri.toString(),name))throw new IOException("Save failed");}catch(Exception failed){Toast.makeText(this,"Couldn’t keep this sound. Choose another audio file.",Toast.LENGTH_LONG).show();}refresh();}
 private void service(String action){Intent intent=new Intent(this,MeditationService.class).setAction(action);if(action.equals(MeditationService.START))startForegroundService(intent);else startService(intent);}
 final class Bridge {
  @JavascriptInterface public String settings(){return MainActivity.this.settings.get().toString();}
  @JavascriptInterface public String state(){return MeditationService.snapshot;}
  @JavascriptInterface public boolean save(String json){return !MeditationService.busy&&settings.save(json);}
  @JavascriptInterface public boolean start(){if(MeditationService.busy)return false;runOnUiThread(()->{preview.stop();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);try{service(MeditationService.START);}catch(RuntimeException failed){Toast.makeText(MainActivity.this,"Couldn’t start the timer. Please try again.",Toast.LENGTH_LONG).show();refresh();}});return true;}
  @JavascriptInterface public void pause(){runOnUiThread(()->service(MeditationService.PAUSE));}
  @JavascriptInterface public void resume(){runOnUiThread(()->service(MeditationService.RESUME));}
  @JavascriptInterface public void stop(){runOnUiThread(()->service(MeditationService.STOP));}
  @JavascriptInterface public void chooseSound(String role){if(MeditationService.busy||(!role.equals("bell")&&!role.equals("quarter")))return;runOnUiThread(()->{pendingRole=role;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),40);}catch(ActivityNotFoundException failed){pendingRole=null;Toast.makeText(MainActivity.this,"No audio file picker is available.",Toast.LENGTH_LONG).show();}});}
  @JavascriptInterface public void preview(String role){if(MeditationService.busy||(!role.equals("bell")&&!role.equals("quarter")))return;runOnUiThread(()->{try{preview.play(settings.get().getString(role),settings.prefs.getString(role+"Uri",""),()->{});}catch(JSONException ignored){}});}
  @JavascriptInterface public void ready(){runOnUiThread(()->{ready=true;web.setAlpha(1);});}
 }
 Bridge bridgeForTests(){return new Bridge();}WebView webForTests(){return web;}
 @android.annotation.TargetApi(33)private static final class BackApi33{static Object register(Activity a,Runnable r){android.window.OnBackInvokedCallback c=r::run;a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,c);return c;}static void unregister(Activity a,Object c){a.getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback((android.window.OnBackInvokedCallback)c);}}
}
